import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Box,
    Typography,
    RadioGroup,
    FormControlLabel,
    Radio,
    Chip,
    Grid,
    Card,
    CardContent,
    Alert
} from '@mui/material';
import {
    Close as CloseIcon,
    PlayArrow as PlayArrowIcon
} from '@mui/icons-material';

import { apiService, ValidParameters } from '../services/api';

interface OptimizationFormProps {
    open: boolean;
    onClose: () => void;
    onStart: (jobId: string, jobType: string) => void;
}

const OptimizationForm: React.FC<OptimizationFormProps> = ({ open, onClose, onStart }) => {
    const [optimizationType, setOptimizationType] = useState<string>('');
    const [cohortMode, setCohortMode] = useState<string>(''); // For cohort sub-options
    const [lob, setLob] = useState<string>('iPhone');
    const [storeType, setStoreType] = useState<string>('flagship');
    const [strategy, setStrategy] = useState<string>('balanced');
    const [validParams, setValidParams] = useState<ValidParameters | null>(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (open) {
            fetchValidParameters();
        }
    }, [open]);

    const fetchValidParameters = async () => {
        try {
            const response = await apiService.getValidParameters();
            if (response.success && response.data) {
                setValidParams(response.data);
            }
        } catch (error) {
            console.error('Failed to fetch valid parameters:', error);
        }
    };

    const handleStart = async () => {
        setLoading(true);
        try {
            let response;

            switch (optimizationType) {
                case 'cohort':
                    if (cohortMode === 'specific_lob') {
                        response = await apiService.startCohortOptimization(lob, storeType);
                    } else if (cohortMode === 'all_lobs') {
                        // Generate for all LOBs
                        response = await apiService.startCohortOptimization('all', storeType);
                    } else if (cohortMode === 'status') {
                        // Show system status
                        response = await apiService.startCohortOptimization('status', storeType);
                    } else {
                        throw new Error('Please select a cohort generation mode');
                    }
                    break;
                case 'lob':
                    response = await apiService.startLOBOptimization(lob, storeType, strategy);
                    break;
                case 'full_store':
                    response = await apiService.startFullStoreOptimization(storeType, strategy);
                    break;
                default:
                    throw new Error('Invalid optimization type');
            }

            if (!response) {
                throw new Error('No response received from server');
            }

            if (response.success && response.data?.job_id) {
                onStart(response.data.job_id, optimizationType);
                onClose();
            } else {
                alert(`Failed to start optimization: ${response.error?.message || 'Unknown error'}`);
            }
        } catch (error: any) {
            console.error('Optimization error:', error);
            alert(`Error starting optimization: ${error.message || 'Network error'}`);
        } finally {
            setLoading(false);
        }
    };

    const getOptimizationDescription = () => {
        switch (optimizationType) {
            case 'cohort':
                if (cohortMode === 'specific_lob') {
                    return `Generate cohort-based planogram for ${lob} accessories in ${storeType} store. Uses customer behavior data and attach rates.`;
                } else if (cohortMode === 'all_lobs') {
                    return `Generate cohort-based planograms for all Lines of Business in ${storeType} store.`;
                } else if (cohortMode === 'status') {
                    return `Show system status and available data for cohort planogram generation.`;
                }
                return 'Select a cohort generation mode to see description.';
            case 'lob':
                return `Optimize ${lob} product line for ${storeType} store using ${strategy} strategy. Includes all product categories for this LOB.`;
            case 'category':
                return `Optimize ${category.replace('_', ' ')} category for ${storeType} store using ${strategy} strategy. Focuses on specific product type.`;
            case 'full_store':
                return `Complete store optimization for ${storeType} store using ${strategy} strategy. Includes all products and categories.`;
            default:
                return 'Select an optimization type to see description.';
        }
    };

    const getAvailableDatasets = () => {
        const datasets = [];

        if (optimizationType === 'cohort' || optimizationType === 'lob') {
            switch (lob) {
                case 'iPhone':
                    datasets.push('iPhone Cases (cases_sales.csv)', 'iPhone Cohort Data (iphone_planogram_cohorts.csv)');
                    break;
                case 'iPad':
                    datasets.push('iPad Cases (ipad-cases-transformed.csv)', 'iPad Cohort Data (ipad_planogram_cohorts.csv)');
                    break;
                case 'Mac':
                    datasets.push('Mac Accessories (mac-accessories-transformed.csv)', 'Mac Cohort Data (mac_planogram_cohorts.csv)');
                    break;
                case 'Watch':
                    datasets.push('Watch Accessories (combined_watch.csv)', 'Watch Cohort Data (watch_planogram_cohorts.csv)');
                    break;
                case 'AirPods':
                    datasets.push('AirPods Data (if available)');
                    break;
            }
        } else if (optimizationType === 'category') {
            switch (category) {
                case 'cases':
                    datasets.push('Phone Cases (cases_sales.csv)');
                    break;
                case 'cables':
                    datasets.push('Cables & Adapters (cables_adapters_sales.csv)');
                    break;
                case 'screen_protectors':
                    datasets.push('Screen Protectors (screen_protectors_sales.csv)');
                    break;
                case 'others':
                    datasets.push('Mounts & Others (mounts_others_sales.csv)');
                    break;
            }
        } else {
            datasets.push('All Available Datasets', 'Processed Data (planogram_sleeves_bags.csv)');
        }

        return datasets;
    };

    const isFormValid = () => {
        if (!optimizationType) return false;

        switch (optimizationType) {
            case 'cohort':
                if (!cohortMode) return false;
                if (cohortMode === 'specific_lob' && !lob) return false;
                break;
            case 'lob':
                if (!lob || !strategy) return false;
                break;
            case 'full_store':
                if (!strategy) return false;
                break;
        }

        return !!storeType;
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
            <DialogTitle>
                <Box display="flex" alignItems="center" justifyContent="space-between">
                    <Typography variant="h6">
                        Configure Planogram Optimization
                    </Typography>
                    <Button onClick={onClose} size="small">
                        <CloseIcon />
                    </Button>
                </Box>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ textAlign: 'center', mb: 4 }}>
                    <Typography variant="h5" gutterBottom>
                        APPLE PLANOGRAM OPTIMIZATION SYSTEM
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                        Select optimization type
                    </Typography>
                </Box>

                <Grid container spacing={3}>
                    {/* Step 1: Choose optimization type */}
                    <Grid item xs={12}>
                        <Card variant="outlined">
                            <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Select optimization type:
                                </Typography>
                                <RadioGroup
                                    value={optimizationType}
                                    onChange={(e) => {
                                        setOptimizationType(e.target.value);
                                        setCohortMode(''); // Reset cohort mode when changing type
                                    }}
                                >
                                    <FormControlLabel
                                        value="cohort"
                                        control={<Radio />}
                                        label="1. Cohort Planogram (Generate cohort-based planograms)"
                                    />
                                    <FormControlLabel
                                        value="lob"
                                        control={<Radio />}
                                        label="2. Line of Business (iPhone, iPad, Mac, etc.)"
                                    />
                                    <FormControlLabel
                                        value="full_store"
                                        control={<Radio />}
                                        label="3. All Products (Full store optimization)"
                                    />
                                </RadioGroup>
                            </CardContent>
                        </Card>
                    </Grid>

                    {/* Cohort Planogram Sub-options */}
                    {optimizationType === 'cohort' && (
                        <Grid item xs={12}>
                            <Card variant="outlined">
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        Choose generation mode:
                                    </Typography>
                                    <RadioGroup
                                        value={cohortMode}
                                        onChange={(e) => setCohortMode(e.target.value)}
                                    >
                                        <FormControlLabel
                                            value="specific_lob"
                                            control={<Radio />}
                                            label="1. Generate for specific Line of Business"
                                        />
                                        <FormControlLabel
                                            value="all_lobs"
                                            control={<Radio />}
                                            label="2. Generate for all Lines of Business"
                                        />
                                        <FormControlLabel
                                            value="status"
                                            control={<Radio />}
                                            label="3. Show system status"
                                        />
                                    </RadioGroup>
                                </CardContent>
                            </Card>
                        </Grid>
                    )}

                    {/* LOB Selection for Cohort or LOB optimization */}
                    {((optimizationType === 'cohort' && cohortMode === 'specific_lob') || optimizationType === 'lob') && (
                        <Grid item xs={12}>
                            <Card variant="outlined">
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        {optimizationType === 'cohort' ? 'Available Lines of Business:' : 'Available Lines of Business:'}
                                    </Typography>
                                    <RadioGroup
                                        value={lob}
                                        onChange={(e) => setLob(e.target.value)}
                                    >
                                        <FormControlLabel value="iPhone" control={<Radio />} label="1. iPhone" />
                                        <FormControlLabel value="iPad" control={<Radio />} label="2. iPad" />
                                        <FormControlLabel value="Mac" control={<Radio />} label="3. Mac" />
                                        <FormControlLabel value="Watch" control={<Radio />} label="4. Watch" />
                                        <FormControlLabel value="AirPods" control={<Radio />} label="5. AirPods" />
                                    </RadioGroup>
                                </CardContent>
                            </Card>
                        </Grid>
                    )}

                    {/* Store Type Selection - Always show if optimization type is selected */}
                    {optimizationType && (
                        <Grid item xs={12}>
                            <Card variant="outlined">
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        Available store types:
                                    </Typography>
                                    <RadioGroup
                                        value={storeType}
                                        onChange={(e) => setStoreType(e.target.value)}
                                    >
                                        {validParams?.store_types.map((storeOption, index) => (
                                            <FormControlLabel
                                                key={storeOption}
                                                value={storeOption}
                                                control={<Radio />}
                                                label={`${index + 1}. ${storeOption.charAt(0).toUpperCase() + storeOption.slice(1)} Store`}
                                            />
                                        ))}
                                    </RadioGroup>
                                </CardContent>
                            </Card>
                        </Grid>
                    )}

                    {/* Optimization Strategy - for LOB and Full Store */}
                    {(optimizationType === 'lob' || optimizationType === 'full_store') && (
                        <Grid item xs={12}>
                            <Card variant="outlined">
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        Optimization strategies:
                                    </Typography>
                                    <RadioGroup
                                        value={strategy}
                                        onChange={(e) => setStrategy(e.target.value)}
                                    >
                                        <FormControlLabel
                                            value="balanced"
                                            control={<Radio />}
                                            label="1. Balanced (considers multiple factors)"
                                        />
                                        <FormControlLabel
                                            value="sales_velocity"
                                            control={<Radio />}
                                            label="2. Sales Velocity (prioritize high-quantity items)"
                                        />
                                        <FormControlLabel
                                            value="category_grouped"
                                            control={<Radio />}
                                            label="3. Category Grouped (group similar products)"
                                        />
                                        <FormControlLabel
                                            value="value_density"
                                            control={<Radio />}
                                            label="4. Value Density (maximize revenue per cm)"
                                        />
                                        <FormControlLabel
                                            value="profit_efficiency"
                                            control={<Radio />}
                                            label="5. Profit Efficiency (maximize profit per cm)"
                                        />
                                    </RadioGroup>
                                </CardContent>
                            </Card>
                        </Grid>
                    )}

                    {/* Configuration Summary */}
                    {optimizationType && (
                        <Grid item xs={12}>
                            <Card variant="outlined">
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        Configuration Summary
                                    </Typography>
                                    <Typography variant="body2" color="text.secondary" paragraph>
                                        {getOptimizationDescription()}
                                    </Typography>

                                    <Box sx={{ mb: 2 }}>
                                        <Typography variant="subtitle2" gutterBottom>
                                            Data Sources:
                                        </Typography>
                                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                                            {getAvailableDatasets().map((dataset, index) => (
                                                <Chip key={index} label={dataset} size="small" variant="outlined" />
                                            ))}
                                        </Box>
                                    </Box>

                                    {(optimizationType === 'lob' || optimizationType === 'full_store') && validParams?.strategy_descriptions[strategy] && (
                                        <Alert severity="info" sx={{ mt: 2 }}>
                                            <strong>Strategy:</strong> {validParams.strategy_descriptions[strategy]}
                                        </Alert>
                                    )}
                                </CardContent>
                            </Card>
                        </Grid>
                    )}
                </Grid>
            </DialogContent>

            <DialogActions>
                <Button onClick={onClose}>
                    Cancel
                </Button>
                <Button
                    onClick={handleStart}
                    variant="contained"
                    disabled={loading || !isFormValid()}
                    startIcon={<PlayArrowIcon />}
                >
                    {loading ? 'Starting...' : 'Start Optimization'}
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default OptimizationForm;
